  /// 8-bit BGRA, opaque; it reaches Dart without a copy (the Dco codec).
  final Uint8List pixels;

  /// Why it failed (`Failed`).
  final FailReason? failReason;

  const ViewEvent({
    required this.kind,
    required this.view,
    this.item,
    required this.generation,
    required this.renderKey,
    required this.x,
    required this.y,
    required this.width,
    required this.height,
    required this.stride,
    required this.pixels,
    this.failReason,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      view.hashCode ^
      item.hashCode ^
      generation.hashCode ^
      renderKey.hashCode ^
      x.hashCode ^
      y.hashCode ^
      width.hashCode ^
      height.hashCode ^
      stride.hashCode ^
      pixels.hashCode ^
      failReason.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ViewEvent &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          view == other.view &&
          item == other.item &&
          generation == other.generation &&
          renderKey == other.renderKey &&
          x == other.x &&
          y == other.y &&
          width == other.width &&
          height == other.height &&
          stride == other.stride &&
          pixels == other.pixels &&
          failReason == other.failReason;
}

/// What a [`ViewEvent`] reports.
enum ViewEventKind {
  /// The view is open: the first event, with its `view` handle.
  opened,

  /// A bitmap is ready: `item`, `generation`, `render_key`, the rectangle and the pixels.
  rendered,

  /// An item could not be rendered: `item`, `generation` and `fail_reason`.
  failed,
}

/// Something a view wants rendered: a tile (`zoom_bucket`, `device_pixel_ratio`, `column`, `row`)
/// or a thumbnail (`size`); the fields of the other kind are 0.
class ViewItem {
  /// Tile or thumbnail.
  final ItemKind kind;

  /// The page, from 0.
  final int page;

  /// A tile's quarter-octave zoom: the logical zoom is 2^(bucket / 4).
  final int zoomBucket;

  /// A tile's device pixel ratio, 0.5 to 4.
  final double devicePixelRatio;

  /// A tile's column on the grid.
  final int column;

  /// A tile's row on the grid.
  final int row;

  /// A thumbnail's side in device pixels, 16 to 1,024.
  final int size;

  const ViewItem({
    required this.kind,
    required this.page,
    required this.zoomBucket,
    required this.devicePixelRatio,
    required this.column,
    required this.row,
    required this.size,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      page.hashCode ^
      zoomBucket.hashCode ^
      devicePixelRatio.hashCode ^
      column.hashCode ^
      row.hashCode ^
      size.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ViewItem &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          page == other.page &&
          zoomBucket == other.zoomBucket &&
          devicePixelRatio == other.devicePixelRatio &&
          column == other.column &&
          row == other.row &&
          size == other.size;
}

/// One entry of a view's wanted set.
class WantedItem {
  /// What to render.
  final ViewItem item;

  /// How urgent it is.
  final Priority priority;

  const WantedItem({required this.item, required this.priority});

  @override
  int get hashCode => item.hashCode ^ priority.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WantedItem &&
          runtimeType == other.runtimeType &&
          item == other.item &&
          priority == other.priority;
}
